def transform(grid):
    h, w = len(grid), len(grid[0])
    # A solid nonzero line separates two equal-sized patterns.
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != 0:
            top, bottom = grid[:r], grid[r+1:]
            if len(top) == len(bottom) and top:
                return [[2 if a != 0 and b != 0 else 0 for a,b in zip(x,y)] for x,y in zip(top,bottom)]
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1 and vals[0] != 0:
            left = [row[:c] for row in grid]
            right = [row[c+1:] for row in grid]
            if c == w-c-1 and c > 0:
                return [[2 if a != 0 and b != 0 else 0 for a,b in zip(x,y)] for x,y in zip(left,right)]
    raise ValueError('no equal halves separated by a solid line')

